'use strict';

/**
 * Stage 10 tests — Final JSON assembly into src/data/siddur/.
 *
 * CJS test file (jest-expo preset does not support .mjs transforms for scripts).
 * Integration tests assert on written output files generated by 10_assemble.mjs.
 */

const { execFileSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const SIDDUR_DIR = path.join(REPO_ROOT, 'src', 'data', 'siddur');
const LEARN_DIR = path.join(SIDDUR_DIR, 'learn');
const STAGE10_SCRIPT = path.join(REPO_ROOT, 'scripts', 'siddur', '10_assemble.mjs');

// Run stage 10 if key outputs are missing
const BOREI_NEFASHOS_PATH = path.join(SIDDUR_DIR, 'birkat_hamazon', 'borei_nefashos.json');
const SHACHARIT_INDEX_PATH = path.join(SIDDUR_DIR, 'shacharit', 'index.ts');
if (!fs.existsSync(BOREI_NEFASHOS_PATH) || !fs.existsSync(SHACHARIT_INDEX_PATH)) {
  console.log('Stage 10 outputs missing — running stage script…');
  execFileSync(process.execPath, [STAGE10_SCRIPT], { stdio: 'inherit' });
}

// ─── Test 1: borei_nefashos.json exists with required SiddurSection fields ───

describe('Stage 10 — borei_nefashos.json is a valid SiddurSection', () => {
  let data;

  beforeAll(() => {
    data = JSON.parse(fs.readFileSync(BOREI_NEFASHOS_PATH, 'utf8'));
  });

  test('file exists', () => {
    expect(fs.existsSync(BOREI_NEFASHOS_PATH)).toBe(true);
  });

  test('has source === feigenbaum', () => {
    expect(data.source).toBe('feigenbaum');
  });

  test('has id field', () => {
    expect(data.id).toBe('borei_nefashos');
  });

  test('has cardId field', () => {
    expect(data.cardId).toBe('birkat_hamazon');
  });

  test('has blocks array', () => {
    expect(Array.isArray(data.blocks)).toBe(true);
    expect(data.blocks.length).toBeGreaterThan(0);
  });

  test('has sourcePages tuple [start, end]', () => {
    expect(Array.isArray(data.sourcePages)).toBe(true);
    expect(data.sourcePages).toHaveLength(2);
  });

  test('has title with en field', () => {
    expect(data.title).toBeDefined();
    expect(typeof data.title.en).toBe('string');
    expect(data.title.en.length).toBeGreaterThan(0);
  });
});

// ─── Test 2: shacharit/index.ts exists and contains hashkamas_haboker ────────

describe('Stage 10 — shacharit/index.ts is correct', () => {
  let content;

  beforeAll(() => {
    content = fs.readFileSync(SHACHARIT_INDEX_PATH, 'utf8');
  });

  test('file exists', () => {
    expect(fs.existsSync(SHACHARIT_INDEX_PATH)).toBe(true);
  });

  test('contains hashkamas_haboker', () => {
    expect(content).toContain('hashkamas_haboker');
  });

  test('contains require() thunk pattern', () => {
    expect(content).toContain('require(');
  });

  test('imports SiddurSection type', () => {
    expect(content).toContain('SiddurSection');
  });

  test('exports SECTIONS const', () => {
    expect(content).toContain('export const SECTIONS');
  });
});

