// ─── Test 4: main index.ts imports from per-card indexes ─────────────────────

describe('Stage 10 — src/data/siddur/index.ts dispatches to per-card indexes', () => {
  let content;
  const INDEX_PATH = path.join(SIDDUR_DIR, 'index.ts');

  beforeAll(() => {
    content = fs.readFileSync(INDEX_PATH, 'utf8');
  });

  test('imports from ./shacharit', () => {
    expect(content).toContain("from './shacharit'");
  });

  test('exports getSiddurSection function', () => {
    expect(content).toContain('export function getSiddurSection');
  });

  test('exports listSectionIds function', () => {
    expect(content).toContain('export function listSectionIds');
  });

  test('does not reference seed fixture', () => {
    expect(content).not.toContain('seed.json');
    expect(content).not.toContain("'seed'");
  });
});

// ─── Test 5: type-conformance checks on assembled sections ───────────────────

describe('Stage 10 — type conformance of assembled blocks', () => {
  test('learn_link blocks use promptText, not label', () => {
    const pitumPath = path.join(SIDDUR_DIR, 'shacharit', 'pitum_haketores.json');
    const data = JSON.parse(fs.readFileSync(pitumPath, 'utf8'));
    const links = data.blocks.filter((b) => b.kind === 'learn_link');
    expect(links.length).toBeGreaterThan(0);
    for (const link of links) {
      expect(link).not.toHaveProperty('label');
      expect(link).toHaveProperty('promptText');
    }
  });

  test('rubric blocks have italic:true', () => {
    const hallelPath = path.join(SIDDUR_DIR, 'shacharit', 'hallel.json');
    const data = JSON.parse(fs.readFileSync(hallelPath, 'utf8'));
    const rubrics = data.blocks.filter((b) => b.kind === 'rubric');
    expect(rubrics.length).toBeGreaterThan(0);
    for (const r of rubrics) {
      expect(r.italic).toBe(true);
      expect(r.text).toBeDefined();
      expect(typeof r.text.en).toBe('string');
    }
  });

  test('date_window conditionalRule uses from/to with kind:month_day', () => {
    const ldovidPath = path.join(SIDDUR_DIR, 'shacharit', 'ldovid_hashem_shacharit.json');
    const data = JSON.parse(fs.readFileSync(ldovidPath, 'utf8'));
    const cr = data.conditionalRule;
    expect(cr).toBeDefined();
    expect(cr.type).toBe('date_window');
    expect(cr.from).toBeDefined();
    expect(cr.from.kind).toBe('month_day');
    expect(typeof cr.from.month).toBe('string');
    expect(typeof cr.from.day).toBe('number');
    expect(cr.to).toBeDefined();
    expect(cr.to.kind).toBe('month_day');
    expect(cr).not.toHaveProperty('start');
    expect(cr).not.toHaveProperty('end');
  });

  test('hallel conditionalRule has variant field', () => {
    const hallelPath = path.join(SIDDUR_DIR, 'shacharit', 'hallel.json');
    const data = JSON.parse(fs.readFileSync(hallelPath, 'utf8'));
    const cr = data.conditionalRule;
    expect(cr).toBeDefined();
    expect(cr.type).toBe('hallel');
    expect(cr.variant).toBeDefined();
    expect(['full', 'half']).toContain(cr.variant);
  });

  test('prayer blocks have no translit in main JSON (moved to sidecar)', () => {
    const hashkamasPath = path.join(SIDDUR_DIR, 'shacharit', 'hashkamas_haboker.json');
    const data = JSON.parse(fs.readFileSync(hashkamasPath, 'utf8'));
    const prayers = data.blocks.filter((b) => b.kind === 'prayer');
    for (const p of prayers) {
      expect(p).not.toHaveProperty('translit');
    }
  });

  test('translit sidecar exists for hashkamas_haboker', () => {
    const sidecarPath = path.join(SIDDUR_DIR, 'shacharit', 'hashkamas_haboker.translit.json');
    expect(fs.existsSync(sidecarPath)).toBe(true);
    const sidecar = JSON.parse(fs.readFileSync(sidecarPath, 'utf8'));
    expect(Array.isArray(sidecar)).toBe(true);
    expect(sidecar.length).toBeGreaterThan(0);
    for (const entry of sidecar) {
      expect(typeof entry.blockIndex).toBe('number');
      expect(Array.isArray(entry.translit)).toBe(true);
    }
  });

  test('callout blocks have no rawText field', () => {
    const hashkamasPath = path.join(SIDDUR_DIR, 'shacharit', 'hashkamas_haboker.json');
    const data = JSON.parse(fs.readFileSync(hashkamasPath, 'utf8'));
    const callouts = data.blocks.filter((b) => b.kind === 'callout' || b.kind === 'instant_insight');
    for (const c of callouts) {
      expect(c).not.toHaveProperty('rawText');
      expect(Array.isArray(c.body)).toBe(true);
    }
  });

  test('block-level conditionalTags hoisted to section-level for krias_hatorah', () => {
    const kriaspath = path.join(SIDDUR_DIR, 'shacharit', 'krias_hatorah.json');
    const data = JSON.parse(fs.readFileSync(kriaspath, 'utf8'));
    // Section-level conditionalTags should exist
    expect(Array.isArray(data.conditionalTags)).toBe(true);
    expect(data.conditionalTags.length).toBeGreaterThan(0);
    // Each entry has blockIndex and rule
    for (const ct of data.conditionalTags) {
      expect(typeof ct.blockIndex).toBe('number');
      expect(ct.blockIndex).toBeGreaterThanOrEqual(0);
      expect(ct.blockIndex).toBeLessThan(data.blocks.length);
      expect(ct.rule).toBeDefined();
      expect(typeof ct.rule.type).toBe('string');
    }
    // No block should still have inline conditionalTags
    for (const block of data.blocks) {
      expect(block).not.toHaveProperty('conditionalTags');
    }
  });
});

